import{_ as t,c as a,o as n,aj as o}from"./chunks/framework.CDhdelVI.js";const c=JSON.parse('{"title":"Folding (No-Knead Dough)","description":"A beginner-friendly guide to folding no-knead dough - an easy technique that builds strength, improves texture, and replaces kneading.","frontmatter":{"title":"Folding (No-Knead Dough)","description":"A beginner-friendly guide to folding no-knead dough - an easy technique that builds strength, improves texture, and replaces kneading.","head":[["meta",{"name":"description","content":"A beginner-friendly guide to folding no-knead dough - an easy technique that builds strength, improves texture, and replaces kneading."}],["meta",{"property":"og:title","content":"Folding (No-Knead Dough)"}],["meta",{"property":"og:description","content":"A beginner-friendly guide to folding no-knead dough - an easy technique that builds strength, improves texture, and replaces kneading."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/folding.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Folding (No-Knead Dough)"}],["meta",{"name":"twitter:description","content":"A beginner-friendly guide to folding no-knead dough - an easy technique that builds strength, improves texture, and replaces kneading."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/folding.html"}]]},"headers":[],"relativePath":"guides/folding.md","filePath":"guides/folding.md"}'),i={name:"guides/folding.md"};function d(r,e,l,s,h,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="folding-for-no-knead-dough" tabindex="-1">Folding (For No-Knead Dough) <a class="header-anchor" href="#folding-for-no-knead-dough" aria-label="Permalink to “Folding (For No-Knead Dough)”">​</a></h1><p>With the <strong>no-knead method</strong>, you rely on time more than mechanical mixing to build structure. Folding is the small intervention that helps the dough catch up: a few quick rounds can improve strength, handling, and final shape without turning the process into a full kneading session.</p><p>If you want the decision framework for when to use no-knead vs kneading, read <a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a>.</p><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Learning when folds help and how to add strength to wet dough without full kneading.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Fold timing, fold count, and the dough changes you should expect after each round.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Pair with fermentation and no-knead vs kneading for the broader process decisions.</span></div></div><p>Each fold takes only a few seconds, and you usually only need a few rounds.</p><h2 id="why-fold-no-knead-dough" tabindex="-1">Why Fold No-Knead Dough? <a class="header-anchor" href="#why-fold-no-knead-dough" aria-label="Permalink to “Why Fold No-Knead Dough?”">​</a></h2><p>Folding helps:</p><ul><li>Strengthen gluten without kneading</li><li>Even out temperature and fermentation</li><li>Create a more open, consistent crumb</li><li>Keep wet dough manageable</li><li>Improve structure and oven spring</li></ul><h2 id="when-to-fold" tabindex="-1">When to Fold <a class="header-anchor" href="#when-to-fold" aria-label="Permalink to “When to Fold”">​</a></h2><p>Right after mixing, the dough is soft, sticky, and shaggy. That is normal. Begin folding <strong>20-30 minutes after mixing</strong>, then repeat a few times during the first hour.</p><p><strong>A typical no-knead schedule uses 2-4 folds spaced 20-30 minutes apart in the first 1 to 2 hours. After that, use occasional gentle folds only if the dough still needs strength.</strong></p><h2 id="how-to-fold-step-by-step" tabindex="-1">How to Fold (Step-by-Step) <a class="header-anchor" href="#how-to-fold-step-by-step" aria-label="Permalink to “How to Fold (Step-by-Step)”">​</a></h2><h3 id="_1-mix-the-dough" tabindex="-1">1. Mix the Dough <a class="header-anchor" href="#_1-mix-the-dough" aria-label="Permalink to “1. Mix the Dough”">​</a></h3><p>After combining flour, water, salt, yeast, and any enrichments, let the dough rest for 20-30 minutes.</p><p>That short rest allows the flour to hydrate and makes the first fold noticeably easier.</p><h3 id="_2-first-fold" tabindex="-1">2. First Fold <a class="header-anchor" href="#_2-first-fold" aria-label="Permalink to “2. First Fold”">​</a></h3><p>Wet your fingers or use a dough scraper:</p><ol><li>Grab one edge of the dough and gently stretch it upward.</li><li>Fold it down toward the center.</li><li>Rotate the bowl a quarter turn.</li><li>Repeat until you have folded all four sides.</li></ol><p>Damp hands prevent sticking, so you can usually skip extra flour.</p><h3 id="_3-repeat-2-3-more-times" tabindex="-1">3. Repeat 2-3 More Times <a class="header-anchor" href="#_3-repeat-2-3-more-times" aria-label="Permalink to “3. Repeat 2-3 More Times”">​</a></h3><p>Do another fold every 20-30 minutes.</p><p>You should notice the dough becoming:</p><ul><li>smoother</li><li>stronger</li><li>more elastic</li></ul><p>That change is the point. If the dough is still slack after a couple of rounds, one more fold cycle usually helps more than immediately adding flour.</p><h2 id="after-folding" tabindex="-1">After Folding <a class="header-anchor" href="#after-folding" aria-label="Permalink to “After Folding”">​</a></h2><p>Once you finish the folding rounds, let the dough continue its bulk fermentation until it has risen noticeably and feels airy. At that point, leave it alone until it is time to divide, shape, or chill.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div>',30)])])}const p=t(i,[["render",d]]);export{c as __pageData,p as default};
